// src/pages/page.js
import React from 'react';
import { graphql } from "gatsby"

import Bio from "../components/bio"
import Layout from "../components/layout"
import Seo from "../components/seo"
import Share from "../components/share"
import Search from "../components/search"

const BlogIndex = ({ data, location }) => {
  const siteTitle = data.site.siteMetadata?.title || `Title`
  const posts = data.allJson.edges
  //console.log(posts)

  return (
      <Layout location={location} title={siteTitle}>

                  <h1 class="main-heading">kobo用EPUBファイルの一覧</h1>
      <Search posts={posts} ext={`kepub`}/>
        <Share
          title={siteTitle}
          url={`${data.site.siteMetadata.siteUrl}`}
          />
            <Bio />
          </Layout>
  )
}

export default BlogIndex

/**
 * Head export to define metadata for the page
 *
 * See: https://www.gatsbyjs.com/docs/reference/built-in-components/gatsby-head/
 */
export const Head = () => <Seo title="青空文庫をEPUBやmobiに変換したものをおいている本棚" />

export const pageQuery = graphql`
query MyQuery {
  site {
    siteMetadata {
      title
      siteUrl
    }
  }
  allJson(filter: {type: {eq: "kepub"}}, sort: {mtime: DESC}) {
    edges {
      node {
        filename
        mtime(formatString: "YYYY年MM月DD日")
      }
    }
  }
}
`
